-- A8 - COMPLETE LOAD
-- Sales Order Foundation (Customer Master + Sales Orders on Finished Goods)
-- ============================================================================

-- FASE 1: DROP (cascade) - tabelas novas, esperado erro 'table not found' na 1a execucao, usar Skip All
DROP TABLE INDUSTRIAL_DATA.SALES_ORDER_ITEM CASCADE;
DROP TABLE INDUSTRIAL_DATA.SALES_ORDER CASCADE;
DROP TABLE INDUSTRIAL_DATA.CUSTOMER CASCADE;
DROP TABLE INDUSTRIAL_DATA.SALES_DOC_TYPE CASCADE;

-- FASE 2: CREATE CONFIG TABLE
CREATE TABLE INDUSTRIAL_DATA.SALES_DOC_TYPE (SALES_DOC_TYPE_CODE NVARCHAR(2) NOT NULL PRIMARY KEY, SALES_DOC_TYPE_TEXT NVARCHAR(60) NOT NULL);

-- FASE 3: LOAD CONFIG DATA

-- FASE 4: CREATE CUSTOMER MASTER
CREATE TABLE INDUSTRIAL_DATA.CUSTOMER (
  KUNNR NVARCHAR(10) NOT NULL PRIMARY KEY,
  KUNNR_TEXT NVARCHAR(80) NOT NULL,
  COUNTRY NVARCHAR(3),
  CURRENCY NVARCHAR(3),
  CREDIT_LIMIT DECIMAL(15, 2),
  FOREIGN KEY (CURRENCY) REFERENCES INDUSTRIAL_DATA.CURRENCY(WAERS),
  CHECK (CREDIT_LIMIT >= 0)
);

-- FASE 5: LOAD CUSTOMER DATA (40 clientes)

-- FASE 6: CREATE SALES ORDER HEADER + ITEM
CREATE TABLE INDUSTRIAL_DATA.SALES_ORDER (
  VBELN NVARCHAR(10) NOT NULL PRIMARY KEY,
  KUNNR NVARCHAR(10) NOT NULL,
  WERKS NVARCHAR(4) NOT NULL,
  SALES_DOC_TYPE_CODE NVARCHAR(2) NOT NULL,
  ORDER_DATE DATE NOT NULL,
  CURRENCY NVARCHAR(3) NOT NULL,
  ITEM_COUNT INT NOT NULL,
  FOREIGN KEY (KUNNR) REFERENCES INDUSTRIAL_DATA.CUSTOMER(KUNNR),
  FOREIGN KEY (WERKS) REFERENCES INDUSTRIAL_DATA.PLANT(WERKS),
  FOREIGN KEY (SALES_DOC_TYPE_CODE) REFERENCES INDUSTRIAL_DATA.SALES_DOC_TYPE(SALES_DOC_TYPE_CODE),
  FOREIGN KEY (CURRENCY) REFERENCES INDUSTRIAL_DATA.CURRENCY(WAERS),
  CHECK (ITEM_COUNT >= 1)
);

CREATE TABLE INDUSTRIAL_DATA.SALES_ORDER_ITEM (
  SO_ITEM_ID INT NOT NULL PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  VBELN NVARCHAR(10) NOT NULL,
  ITEM_NO INT NOT NULL,
  MATNR NVARCHAR(10) NOT NULL,
  QUANTITY DECIMAL(15, 2) NOT NULL,
  NET_PRICE DECIMAL(15, 2) NOT NULL,
  SHIP_DATE DATE,
  FOREIGN KEY (VBELN) REFERENCES INDUSTRIAL_DATA.SALES_ORDER(VBELN),
  FOREIGN KEY (MATNR) REFERENCES INDUSTRIAL_DATA.MATERIAL(MATNR),
  CHECK (QUANTITY > 0),
  CHECK (NET_PRICE >= 0)
);

-- FASE 7: LOAD SALES ORDER HEADERS (40 pedidos, distribuicao variavel de itens: 1/3/5/8/11)

-- FASE 8: LOAD SALES ORDER ITEMS (187 itens)

-- FASE 9: VALIDACAO FINAL
SELECT 'A8 LOADED SUCCESSFULLY' FROM DUMMY;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.SALES_DOC_TYPE;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.CUSTOMER;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.SALES_ORDER;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.SALES_ORDER_ITEM;
SELECT ITEM_COUNT, COUNT(*) FROM INDUSTRIAL_DATA.SALES_ORDER GROUP BY ITEM_COUNT ORDER BY ITEM_COUNT;
SELECT TOP 5 VBELN, KUNNR, WERKS, SALES_DOC_TYPE_CODE, ITEM_COUNT FROM INDUSTRIAL_DATA.SALES_ORDER ORDER BY VBELN;
